// n8n's HTTP Request node auto-splits a top-level JSON array response
// into one item per element, so each profile already arrives as its own item.
const profiles = $input.all().map(item => item.json);

const now = new Date();

function localHour(ianaZone) {
  try {
    const formatted = new Intl.DateTimeFormat('en-US', {
      hour: 'numeric',
      hour12: false,
      timeZone: ianaZone
    }).format(now);
    // Intl returns '24' for midnight in some locales — normalize to 0.
    const h = parseInt(formatted, 10);
    return h === 24 ? 0 : h;
  } catch {
    // Fall back to UTC if the timezone string is invalid.
    return now.getUTCHours();
  }
}

function fmt12(h) {
  const norm = ((h % 24) + 24) % 24;
  const suffix = norm >= 12 ? 'PM' : 'AM';
  const hour = norm % 12 || 12;
  return `${hour}:00 ${suffix}`;
}

const messages = [];

for (const p of profiles) {
  const chatId = String(p.telegram_chat_id ?? '').trim();
  if (!chatId) continue;

  const fastStart = Number(p.fasting_start_hour ?? 20);  // default 8 PM
  const duration = Number(p.fasting_duration_hours ?? 16);
  const tz = p.fasting_tz || 'America/New_York';

  const eatStart = (fastStart + duration) % 24;
  const warnFast = ((fastStart - 1) + 24) % 24;
  const warnEat = ((eatStart - 1) + 24) % 24;
  const energyCheckHour = (eatStart + 2) % 24;  // 2 hours after eating window opens

  const curHour = localHour(tz);
  let text = null;

  if (curHour === warnFast) {
    text = `Heads up: your fast starts in 1 hour at ${fmt12(fastStart)}. Finish eating soon and hydrate well.`;
  } else if (curHour === fastStart) {
    text = `Your ${duration}-hour fast has started. Your eating window opens at ${fmt12(eatStart)}. Drink water and stay consistent.`;
  } else if (curHour === warnEat) {
    text = `Your eating window opens in 1 hour at ${fmt12(eatStart)}. Start thinking about your first meal — prioritize protein.`;
  } else if (curHour === eatStart) {
    text = `Time to eat! Your eating window is open. Break your fast with something nourishing. Protein first.`;
  } else if (curHour === energyCheckHour) {
    text = `Energy check-in: how are you feeling right now?\n\nReply with a number:\n1 - Exhausted\n2 - Low\n3 - Okay\n4 - Good\n5 - Great\n\n(We'll add in-app logging soon.)`;
  }

  if (text) {
    messages.push({ json: { chatId, text } });
  }
}

return messages;
